def solution(n):
    # Count every number's bits from scratch: check all 32 bit positions.
    # O(32 * n) work instead of O(n).
    ans = []
    for i in range(n + 1):
        count = 0
        for b in range(32):
            if (i >> b) & 1:
                count += 1
        ans.append(count)
    return ans
